// Generates review-dispatch fixtures: GitHub REST responses trimmed to the fields the tool reads.
// Run: node tools/test/fixtures/make-health-dispatch.mjs tools/test/fixtures
import fs from "node:fs";
const OUT = process.argv[2];
const NOW = Date.parse("2026-11-14T00:00:00Z");
const at = (days) => new Date(NOW - days * 86400000).toISOString();
const sha = (c) => c.repeat(40);
const R = "repos/statewalker/statewalker-root";
const record = (number, project, state, createdDays, closedDays = null) => ({
  number, title: `Health review: ${project}`, state, created_at: at(createdDays), closed_at: closedDays == null ? null : at(closedDays),
  labels: [{ name: "health-review" }, { name: `repo:${project}` }],
});
const done = (project, commit) => ({ body: `## Record\n\n...\n\n<!-- health-review: project=${project} commit=${commit} -->\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_` });
const say = (body) => ({ body });
const bug = (number, days, title = `Bug ${number}`) => ({ number, title, created_at: at(days), labels: [{ name: "bug" }] });
const noBugs = (repo) => ({ [`repos/statewalker/${repo}/issues?state=open&labels=bug,review-followup`]: [], [`repos/statewalker/${repo}/issues?state=open&labels=bug,health-review`]: [] });
const head = (repo, c) => ({ [`repos/statewalker/${repo}/commits/main`]: { sha: sha(c) } });

fs.writeFileSync(`${OUT}/health-dispatch-layers.json`, JSON.stringify({
  "p-released": 2, "p-claimed": 1, "p-first": 3, "p-first-low": 0, "p-unchanged": 0, "p-old": 5, "p-recent": 0,
}, null, 1) + "\n");

const data = {
  [`${R}/issues?state=all&labels=health-review`]: [
    record(101, "p-released", "open", 10),
    record(102, "p-claimed", "open", 3),
    record(90, "p-unchanged", "closed", 20, 14),
    record(91, "p-old", "closed", 32, 30),
    record(89, "p-old", "closed", 60, 58),       // older run, superseded by #91
    record(93, "p-old", "closed", 5, 4),          // closed without a record line (abandoned): ignored
    record(92, "p-recent", "closed", 8, 7),
    { number: 120, title: "Health review: p-first", state: "open", created_at: at(1), pull_request: {}, labels: [] }, // a PR, ignored
  ],
  [`${R}/issues/101/comments`]: [say("Claimed by https://claude.ai/code/session_a"), say("Released: ran out of time")],
  [`${R}/issues/102/comments`]: [say("Claimed by https://claude.ai/code/session_b"), say("Progress: halfway")],
  [`${R}/issues/90/comments`]: [done("p-unchanged", sha("a").slice(0, 12))],
  [`${R}/issues/91/comments`]: [say("Claimed by x"), done("p-old", sha("b"))],
  [`${R}/issues/93/comments`]: [say("Claimed by y"), say("Closing: started by mistake.")],
  [`${R}/issues/92/comments`]: [done("p-recent", sha("c"))],
  [`${R}/issues?state=open&labels=bug`]: [
    { number: 200, title: "Deferred bug: p-first#3 Old crash", body: "Links https://github.com/statewalker/p-first/issues/3 here." },
    { number: 201, title: "Deferred bug: p-old#70 Other", body: "Links https://github.com/statewalker/p-old/issues/70." }, // not a link to #7
  ],
  ...head("p-released", "1"), ...head("p-claimed", "2"), ...head("p-first", "3"), ...head("p-first-low", "4"),
  ...head("p-unchanged", "a"), ...head("p-old", "5"), ...head("p-recent", "6"),
  ...noBugs("p-released"), ...noBugs("p-claimed"), ...noBugs("p-first-low"), ...noBugs("p-unchanged"), ...noBugs("p-recent"),
  "repos/statewalker/p-old/issues?state=open&labels=bug,review-followup": [bug(7, 28, "Exactly four weeks"), bug(8, 27.9, "Not yet")],
  "repos/statewalker/p-old/issues?state=open&labels=bug,health-review": [bug(7, 28, "Exactly four weeks")],
  "repos/statewalker/p-first/issues?state=open&labels=bug,review-followup": [bug(3, 60, "Old crash")],
  "repos/statewalker/p-first/issues?state=open&labels=bug,health-review": [],
};
fs.writeFileSync(`${OUT}/health-dispatch.json`, JSON.stringify(data, null, 1) + "\n");

// Two real projects, both never reviewed: the order comes from CLAUDE.md's layer table.
fs.writeFileSync(`${OUT}/health-dispatch-claude-md.json`, JSON.stringify({
  [`${R}/issues?state=all&labels=health-review`]: [],
  [`${R}/issues?state=open&labels=bug`]: [],
  ...head("statewalker-sandbox", "7"), ...head("webrun-files", "8"), ...head("statewalker-shared", "9"),
  ...noBugs("statewalker-sandbox"), ...noBugs("webrun-files"), ...noBugs("statewalker-shared"),
}, null, 1) + "\n");

// More unfinished runs than the cap: six open record tickets, no comments.
const six = ["q1", "q2", "q3", "q4", "q5", "q6"];
fs.writeFileSync(`${OUT}/health-dispatch-cap.json`, JSON.stringify(Object.assign(
  { [`${R}/issues?state=all&labels=health-review`]: six.map((q, i) => record(300 + i, q, "open", 10 - i)), [`${R}/issues?state=open&labels=bug`]: [] },
  ...six.map((q, i) => ({ [`${R}/issues/${300 + i}/comments`]: [], ...head(q, "d"), ...noBugs(q) })),
), null, 1) + "\n");
